fn is_digit(c: Int) -> Bool {
  return c >= 48 and c <= 57
}

fn unit_rank(c: Int) -> Int {
  if c == 100 {
    return 1
  }
  if c == 104 {
    return 2
  }
  if c == 109 {
    return 3
  }
  if c == 115 {
    return 4
  }
  return 0
}

fn unit_size(rank: Int) -> Int {
  if rank == 1 {
    return 86400
  }
  if rank == 2 {
    return 3600
  }
  if rank == 3 {
    return 60
  }
  return 1
}

pub fn duration(s: Str) -> Result[Int, Str] {
  let cs = s.codes()
  let n = cs.len()
  var p = 0
  var total = 0
  var last = 0
  while p < n {
    var num = 0
    var digits = 0
    while p < n and is_digit(cs.get_or(p, 0)) {
      num = num * 10 + (cs.get_or(p, 0) - 48)
      digits = digits + 1
      p = p + 1
    }
    if digits == 0 or p >= n {
      return Err("invalid duration")
    }
    let rank = unit_rank(cs.get_or(p, 0))
    if rank == 0 or rank <= last {
      return Err("invalid duration")
    }
    total = total + num * unit_size(rank)
    last = rank
    p = p + 1
  }
  if last == 0 {
    return Err("invalid duration")
  }
  return Ok(total)
}
